import { log } from './log'

type MailOptions = {
  to: string
  subject: string
  text?: string
  html?: string
  replyTo?: string
  /** Overrides FROM_EMAIL / SMTP_USER (an address, or a display name with an address). */
  from?: string | { name: string; address: string }
  bcc?: string
  /** Message-ID to send with ("<id@host>"); generated by nodemailer when absent. */
  messageId?: string
  /** Threading (RFC 5322 §3.6.4). */
  inReplyTo?: string
  references?: string[]
}

/**
 * Send mail via SMTP when configured; otherwise skip quietly.
 *
 * Never logs message bodies — they can carry password-reset links and
 * contact-form personal data. Timeouts keep a dead SMTP server from holding
 * an API request open. Returns the sent message's Message-ID when known.
 */
export async function sendMail(opts: MailOptions): Promise<{ ok: boolean; skipped?: boolean; messageId?: string }> {
  const host = process.env.SMTP_HOST
  const port = Number(process.env.SMTP_PORT || 587)
  const user = process.env.SMTP_USER
  const pass = process.env.SMTP_PASS
  const from = opts.from || process.env.FROM_EMAIL || user

  if (!host || !user || !pass || !from) {
    log.info('mail: SMTP not configured, message skipped', { subject: opts.subject, to: opts.to })
    return { ok: false, skipped: true }
  }
  // Loaded only when SMTP is configured (nodemailer ships its own types).
  const { createTransport } = await import('nodemailer')
  const transporter = createTransport({
    host,
    port,
    secure: port === 465,
    auth: { user, pass },
    connectionTimeout: 10_000,
    greetingTimeout: 10_000,
    socketTimeout: 20_000,
  })
  const info = await transporter.sendMail({
    from,
    to: opts.to,
    subject: opts.subject,
    text: opts.text,
    html: opts.html,
    ...(opts.replyTo ? { replyTo: opts.replyTo } : {}),
    ...(opts.bcc ? { bcc: opts.bcc } : {}),
    ...(opts.messageId ? { messageId: opts.messageId } : {}),
    ...(opts.inReplyTo ? { inReplyTo: opts.inReplyTo } : {}),
    ...(opts.references?.length ? { references: opts.references } : {}),
  })
  const messageId = typeof info?.messageId === 'string' ? info.messageId : opts.messageId
  return { ok: true, ...(messageId ? { messageId } : {}) }
}

export function siteUrl() {
  return process.env.SITE_URL || 'https://lucian-dev.com'
}

/** Host part for generated Message-IDs ("lucian-dev.com"). */
export function messageIdHost(): string {
  try {
    return new URL(siteUrl()).hostname || 'localhost'
  } catch {
    return 'localhost'
  }
}
